def mode(values):
    """Return the most common value in `values`.

    `values` is a list of numbers (ints or floats). Raises ValueError if
    `values` is empty. If there is a tie for the most common value,
    returns the smallest of the tied values.
    """
    if not values:
        raise ValueError("values must not be empty")
    counts = {}
    for v in values:
        counts[v] = counts.get(v, 0) + 1
    max_count = max(counts.values())
    tied = [k for k, c in counts.items() if c == max_count]
    return min(tied)}

